from os.path import join as pathjoin
import traceback as tb

from sys import stdout, stderr

# global log levels
ERROR = 0
WARNING = 1
INFO = 2
DEBUG = 3

_COLORS = {
    "fg black": "\033[30m",
    "fg red": "\033[31m",
    "fg green": "\033[32m",
    "fg yellow": "\033[33m",
    "fg blue": "\033[34m",
    "fg magenta": "\033[35m",
    "fg cyan": "\033[36m",
    "fg white": "\033[37m",
    #
    "fg bright black": "\033[90m",
    "fg bright red": "\033[91m",
    "fg bright green": "\033[92m",
    "fg bright yellow": "\033[93m",
    "fg bright blue": "\033[94m",
    "fg bright magenta": "\033[95m",
    "fg bright cyan": "\033[96m",
    "fg bright white": "\033[97m",
    #
    "bg black": "\033[40m",
    "bg red": "\033[41m",
    "bg green": "\033[42m",
    "bg yellow": "\033[43m",
    "bg blue": "\033[44m",
    "bg magenta": "\033[45m",
    "bg cyan": "\033[46m",
    "bg white": "\033[47m",
    #
    "bg bright black": "\033[100m",
    "bg bright red": "\033[101m",
    "bg bright green": "\033[102m",
    "bg bright yellow": "\033[103m",
    "bg bright blue": "\033[104m",
    "bg bright magenta": "\033[105m",
    "bg bright cyan": "\033[106m",
    "bg bright white": "\033[107m",
    #
    "default": "\033[0m",
}
_COLOR_RESET = ["default"]


class Logger:
    """A logger class to be used from all other classes"""

    _actioncount = 0
    _LOG_REPR = {
        "ERROR": "!ERR",
        "WARNING": "WARN",
        "INFO": "info",
        "CONFIRM": "info",
        "DEBUG": " dbg",
    }

    _LOG_COLORS = {
        "ERROR": ["fg red", "bg bright white"],
        "WARNING": ["fg bright yellow"],
        "INFO": ["fg white"],
        "CONFIRM": ["fg green"],
        "DEBUG": ["fg bright black"],
    }
    _DEFAULT_PATH = "./"

    def wrap_call(self, function):
        """a decorator from a logger instance"""

        def wrapper(*args, **kwargs):
            try:
                if __debug__:
                    self.debug(
                        f"CALLED function {function.__name__}",
                        f"args  : {args}",
                        f"kwargs: {kwargs}",
                    )
                # if self._loglevel > 2:
                self._indentlevel += 1
                ret = function(*args, **kwargs)
                if __debug__:
                    self.debug(f"return value: {ret}")
                    self.debug("done")
            except Exception as exc:
                if self._alerted:
                    control_message = "Error! An exception occured"
                else:
                    control_message = "A controlled exception occured"
                lines = [
                    f"{control_message}: {exc}",
                    f"called generator {function.__name__}",
                    f"args  : {args}",
                    f"kwargs: {kwargs}",
                ]
                if self._alerted:
                    lines.append("traceback:")
                    for num, segment in enumerate(
                        tb.format_tb(exc.__traceback__, limit=None)
                    ):
                        # if num == 0:
                        #     continue
                        for line in segment.split("\n"):
                            if line.strip():
                                lines.append(f"  {line}")
                    self.error(*lines)
                else:
                    self.warn(*lines)
                exc.add_note(
                    f"Information has been written to the log file '{self._file}'"
                )
                raise exc
            finally:
                # if self._loglevel > 2:
                self._indentlevel -= 1
                self.debug(f"END of function {function.__name__}")
            return ret

        # potential TODO: tidy the stacktrace from the logger parts

        return wrapper

    def wrap_call_gen(self, function):
        """a decorator from a logger instance"""

        def wrapper(*args, **kwargs):
            try:
                if __debug__:
                    self.debug(
                        f"CALLED generator {function.__name__}",
                        f"args  : {args}",
                        f"kwargs: {kwargs}",
                    )
                # if self._loglevel > 2:
                self._indentlevel += 1
                for ret in function(*args, **kwargs):
                    if __debug__:
                        self.debug(f"yield value: {ret}")
                    yield ret
                if __debug__:
                    self.debug("done")
            except Exception as exc:
                if self._alerted:
                    control_message = "Error! An exception occured"
                else:
                    control_message = "A controlled exception occured"
                lines = [
                    f"{control_message}: {exc}",
                    f"called generator {function.__name__}",
                    f"args  : {args}",
                    f"kwargs: {kwargs}",
                ]
                if self._alerted:
                    lines.append("traceback:")
                    for num, segment in enumerate(
                        tb.format_tb(exc.__traceback__, limit=None)
                    ):
                        # if num == 0:
                        #     continue
                        for line in segment.split("\n"):
                            if line.strip():
                                lines.append(f"  {line}")
                    self.error(*lines)
                else:
                    self.warn(*lines)
                exc.add_note(
                    f"Information has been written to the log file '{self._file}'"
                )
                raise exc
            finally:
                # if self._loglevel > 2:
                self._indentlevel -= 1
                self.debug(f"END of generator {function.__name__}")
            return ret

        # potential TODO: tidy the stacktrace from the logger parts

        return wrapper

    def controlled(self, function):
        """a decorator to alert that any exception is fatal within"""

        def wrapper(*args, **kwargs):
            self._alerted = False
            ret = function(*args, **kwargs)
            self._alerted = True
            return ret

        return wrapper

    def __init__(self, filename=None, path=None, loglevel=2, stdout=False):
        """supported kwargs: stdout (False), stderr(True)"""
        self._file = None
        self._alerted = True
        self._file = None
        self._indentlevel = 0
        self._loglevel = min(3, max(0, loglevel))
        self._stdout = stdout

        self.set_logfile(filename, path, reset=True)

    def reset(self):
        """reset the file"""
        if self._file:
            with open(self._file, "w") as file:
                file.write("")

    def set_loglevel(self, loglevel):
        """
        Set the loglevel.

        0: include only errors
        1: also include warnings
        2: also include info (default)
        3: also include debug info
        """
        self._loglevel = min(3, max(0, loglevel))

    def set_logfile(self, filename, path=None, reset=True):
        """
        Set the logfile and path
        """
        if filename is None:
            # reset file?
            self._file = None
        else:
            if not filename.endswith(".log"):
                if not "." in filename:
                    filename = filename + ".log"
            if path is None:
                # default path if not explicitely set
                path = Logger._DEFAULT_PATH
            self._file = pathjoin(path, filename)
            if reset:
                self.reset()

    def _write_to_stdout(self, acstr, typestr, mline, msgtype, level, srcstr):
        indent = level * "  "
        colors_in, colors_out = Logger._LOG_COLORS[msgtype], _COLOR_RESET
        color_in = "".join((_COLORS[col] for col in colors_in))
        color_out = "".join((_COLORS[col] for col in colors_out))
        line = color_in + f"{indent}{mline}" + color_out
        # line = color_in + f"{srcstr}{indent}{mline}" + color_out
        # line = color_in + f"{acstr}{srcstr}{typestr}{indent}{mline}" + color_out
        if msgtype == "ERROR":
            stderr.write(line + "\n")
        else:
            if self._stdout:
                stdout.write(line + "\n")

    def _write_to_file(self, acstr, typestr, mline, msgtype, level, srcstr):
        indent = level * "  "
        line = f"{acstr}{srcstr}{typestr}{indent}{mline}"
        if self._file:
            with open(self._file, "a") as file:
                file.write(line + "\n")

    def multiline_log(
        self, message_lines, msgtype="INFO", level=None, source=None
    ):
        """log multiple lines"""
        if level is None:
            level = self._indentlevel
        if source is None:
            source = __name__
        ssource = source.strip()
        lsource = source.strip()
        if len(ssource) > 12:
            ssource = ".." + ssource[-10:]
        if len(lsource) > 22:
            lsource = ".." + lsource[-20:]

        if "".join(message_lines).replace("\n", "").strip():
            acount = Logger._actioncount
            Logger._actioncount += 1

            first = True
            for mline in message_lines:
                acstr = f"{acount:>6}" + ": "
                typestr = f"{type(self)._LOG_REPR[msgtype.upper()]: <4}" + ": "
                lsrcstr = f"@{lsource:<22}: "
                ssrcstr = f"@{ssource:<12}: "
                if not first:
                    acstr = " " * len(acstr)
                    typestr = " " * len(typestr)
                    lsrcstr = " " * len(lsrcstr)
                    ssrcstr = " " * len(ssrcstr)
                first = False
                self._write_to_stdout(
                    acstr, typestr, mline, msgtype, level, ssrcstr
                )
                if mline.strip():
                    self._write_to_file(
                        acstr, typestr, mline, msgtype, level, lsrcstr
                    )
        else:
            self._write_to_stdout("", "", "", msgtype, level, "")

    def log(self, message, msgtype="INFO", level=None, source=None):
        """log a line"""
        self.multiline_log(
            [message], msgtype=msgtype, level=level, source=source
        )

    def _log_debug(self, *messages, source=None):
        if self._loglevel > 2:
            self.multiline_log(list(messages), "DEBUG", source=source)

    def _log_info(self, *messages, source=None):
        if self._loglevel > 1:
            self.multiline_log(list(messages), "INFO", source=source)

    def _log_success(self, message, source=None):
        if self._loglevel > 1:
            self.multiline_log([message], "CONFIRM", source=source)

    def _log_warn(self, *messages, source=None):
        if self._loglevel > 0:
            self.multiline_log(list(messages), "WARNING", source=source)

    def _log_error(self, *messages, source=None):
        self.multiline_log(list(messages), "ERROR", source=source)

    def info(self, *messages, source=None):
        """make an info log message"""
        return self._log_info(
            *sum((msg.split("\n") for msg in messages), start=[]),
            source=source,
        )

    def success(self, message="done!", source=None):
        """make a success log message"""
        return (self._log_success(message, source=source),)

    def debug(self, *messages, source=None):
        """make a debug log message"""
        return self._log_debug(
            *sum((msg.split("\n") for msg in messages), start=[]),
            source=source,
        )

    def warn(self, *messages, source=None):
        """make a warning log message"""
        return self._log_warn(
            *sum((msg.split("\n") for msg in messages), start=[]),
            source=source,
        )

    def error(self, *messages, source=None):
        """make an error log message"""
        return self._log_error(
            *sum((msg.split("\n") for msg in messages), start=[]),
            source=source,
        )


